import { describe, test, expect } from 'vitest';
import GBNF, { GBNF as named, RuleType } from 'gbnf';

describe('smoke', () => {
  test('exposes size, grammar, print and named exports', () => {
    const state = GBNF('root ::= "foo" | [a-z]');
    expect(named).toBe(GBNF);
    expect(RuleType.CHAR).toBe('char');
    expect(state.size).toBe(2);
    expect(state.grammar).toBe('root ::= "foo" | [a-z]');
    expect([...state.rules()].length).toBe(2);
    const printed = GBNF('root ::= foo\nfoo ::= "a"');
    expect(typeof (printed as any).constructor).toBe('function');
  });
  test('graph print renders', async () => {
    const { Graph, RulesBuilder, buildRuleStack } = await import('gbnf');
    const grammar = 'root ::= "ab" | [a-z] | foo\nfoo ::= "z"';
    const rb = new RulesBuilder(grammar);
    const graph = new Graph(grammar, rb.rules.map(buildRuleStack), rb.symbolIds.get('root')!);
    const out = graph.print(undefined, false);
    expect(out.length).toBeGreaterThan(0);
    expect(graph.print(undefined, true)).toContain('\x1b[');
  });
});
EOF
